function f(n) {
    const result = [];

    for (let i = 1; i <= n; i++) {
        if (i % 2 === 0) {
            result.push(factorial(i));
        } else {
            result.push(sumTo(i));
        }
    }

    return result;

    function factorial(num) {
        let product = 1;
        for (let j = 1; j <= num; j++) {
            product *= j;
        }
        return product;
    }

    function sumTo(num) {
        return (num * (num + 1)) / 2;
    }
}

