  for (let i = 1; i < n; i++) {
    const rotated = str.slice(i) + str.slice(0, i);
    if (rotated === str) {
      return i;
    }
  }
  return n; // If no rotation matches, return the length of the string
}

function find_kth(arr1, arr2, k) {
    let i = 0, j = 0;
    while (i < arr1.length && j < arr2.length) {
        if (arr1[i] < arr2[j]) {
            i++;
        } else {
            j++;
        }
        k--;
        if (k === 0) {
            return arr1[i] < arr2[j] ? arr1[i] : arr2[j];
        }
    }
    while (i < arr1.length) {
        k--;
        if (k === 0) {
            return arr1[i];
        }
        i++;
