            return arr2[j];
        }
        j++;
    }
}

function find_kth(arr1, arr2, k) {
    let i = 0, j = 0;
    while (i < arr1.length && j < arr2.length) {
        if (arr1[i] < arr2[j]) {
            i++;
        } else {
            j++;
        }
    }
    if (i === arr1.length) {
        return arr2[j + k - 1];
    } else if (j === arr2.length) {
        return arr1[i + k - 1];
    } else {
        return Math.min(arr1[i], arr2[j]);
    }
}

