function Strongest_Extension(class_name, extensions){
    let strongestExtension = '';
    let highestStrength = -Infinity;

    for (let extension of extensions) {
        let cap = (extension.match(/[A-Z]/g) || []).length;
        let sm = (extension.match(/[a-z]/g) || []).length;
        let strength = cap - sm;

        if (strength > highestStrength) {
            highestStrength = strength;
            strongestExtension = extension;
        }
    }

    return `${class_name}.${strongestExtension}`;
}

function hex_key(num) {
  const primeHexDigits = new Set(['2', '3', '5', '7', 'B', 'D']);
  let count = 0;
  for (let i = 0; i < num.length; i++) {
    if (primeHexDigits.has(num[i])) {
      count++;
    }
  }
  return count;
}

