function get_closest_vowel(word) {
  const vowels = 'aeiouAEIOU';
  let closestVowel = '';

  for (let i = word.length - 2; i > 0; i--) {
    if (vowels.includes(word[i]) && !vowels.includes(word[i - 1]) && !vowels.includes(word[i + 1])) {
      closestVowel = word[i];
      break;
    }
  }

  return closestVowel;
}

function min_Swaps(str1, str2){
    let count0 = 0;
    let count1 = 0;
    for(let i = 0; i < str1.length; i++){
        if(str1[i] === '0') count0++;
        if(str2[i] === '0') count0--;
        if(str1[i] === '1') count1++;
        if(str2[i] === '1') count1--;
    }
    if((count0 + count1) % 2 !== 0) return -1;
    return (Math.abs(count0) + Math.abs(count1)) / 2;
}

function min_Swaps(str1, str2) {
    let count0 = 0;
    let count1 = 0;

    for (let i = 0; i < str1.length; i++) {
        if (str1[i] !== str2[i]) {
            if (str1[i] === '0') {
                count0++;
            } else {
                count1++;
            }
        }
    }

    if ((count0 + count1) % 2 !== 0) {
        return -1; // Not possible to make them equal
    }

    return Math.min(count0, count1) / 2;
}

