function max_difference(test_list){
    if (test_list.length < 2) {
        return 0; // Not enough elements to form a pair
    }
    test_list.sort((a, b) => a - b);
    let max_diff = 0;
    for (let i = 0; i < test_list.length - 1; i++) {
        max_diff = Math.max(max_diff, test_list[i + 1] - test_list[i]);
    }
    return max_diff;
}
